import{_ as a,o,c as r,a3 as s}from"./chunks/framework.rPoJfhSN.js";const m=JSON.parse('{"title":"Seguridad","description":"","frontmatter":{},"headers":[],"relativePath":"operacion/seguridad.md","filePath":"operacion/seguridad.md","lastUpdated":1786330671000}'),i={name:"operacion/seguridad.md"};function n(d,e,c,t,l,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="seguridad" tabindex="-1">Seguridad <a class="header-anchor" href="#seguridad" aria-label="Permalink to &quot;Seguridad&quot;">​</a></h1><h2 id="antes-de-vender-u-operar" tabindex="-1">Antes de vender u operar <a class="header-anchor" href="#antes-de-vender-u-operar" aria-label="Permalink to &quot;Antes de vender u operar&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Prioridad alta</p><p>El snapshot y algunos seeders contienen datos de demostración. Nunca publiques credenciales conocidas ni reutilices claves sandbox. Cambia contraseñas, <code>APP_KEY</code>, accesos de base, correo y pasarelas en cada entorno.</p></div><h2 id="controles-esenciales" tabindex="-1">Controles esenciales <a class="header-anchor" href="#controles-esenciales" aria-label="Permalink to &quot;Controles esenciales&quot;">​</a></h2><ul><li><code>APP_DEBUG=false</code> y HTTPS en producción.</li><li>Cookies seguras, <code>HttpOnly</code> y política <code>SameSite</code> apropiada.</li><li>Autorización por recurso con políticas y permisos mínimos.</li><li>Validación de tipo, tamaño y contenido en uploads; nombres generados por servidor.</li><li>Documentos KYC en disco privado, servidos sólo mediante controlador autorizado.</li><li>Rate limiting en login, recuperación, contacto, cupones, checkout y callbacks.</li><li>CSRF en formularios web y firma/verificación en webhooks.</li><li>Secretos fuera del repositorio y rotación documentada.</li><li>Dependencias auditadas y actualizadas con pruebas.</li><li>Backups cifrados y restauraciones ensayadas.</li></ul><h2 id="servidores-de-desarrollo" tabindex="-1">Servidores de desarrollo <a class="header-anchor" href="#servidores-de-desarrollo" aria-label="Permalink to &quot;Servidores de desarrollo&quot;">​</a></h2><p>Vite y la versión estable actual de VitePress arrastran avisos de seguridad que afectan al servidor de desarrollo, no a los archivos estáticos generados. Por eso los comandos <code>docs:dev</code> y <code>docs:preview</code> escuchan únicamente en <code>127.0.0.1</code>. No los expongas a Internet: publica sólo el contenido generado en <code>public/docs</code> detrás de Nginx o Apache.</p><h2 id="pagos-y-dinero" tabindex="-1">Pagos y dinero <a class="header-anchor" href="#pagos-y-dinero" aria-label="Permalink to &quot;Pagos y dinero&quot;">​</a></h2><p>La página de éxito del navegador no prueba por sí sola un pago. Verifica el evento directamente con la pasarela o mediante webhook firmado. Guarda el identificador externo con restricción única y rechaza repeticiones.</p><p>Pedidos, comisión, cartera y retiro deben usar transacciones. Para retiros, bloquea la fila de saldo, valida el estado previo y registra un movimiento contable inmutable.</p><h2 id="datos-personales" tabindex="-1">Datos personales <a class="header-anchor" href="#datos-personales" aria-label="Permalink to &quot;Datos personales&quot;">​</a></h2><p>Clasifica direcciones, teléfono, documentos KYC y datos bancarios. Define retención, borrado, acceso interno y respuesta a incidentes conforme al mercado donde opere Plazora. Evita incluir información sensible en logs.</p><h2 id="cabeceras-recomendadas" tabindex="-1">Cabeceras recomendadas <a class="header-anchor" href="#cabeceras-recomendadas" aria-label="Permalink to &quot;Cabeceras recomendadas&quot;">​</a></h2><p>Configura progresivamente Content Security Policy, <code>Referrer-Policy</code>, <code>X-Content-Type-Options</code>, permisos del navegador y protección contra framing. Prueba pagos y assets externos antes de endurecer CSP.</p><h2 id="respuesta-a-incidentes" tabindex="-1">Respuesta a incidentes <a class="header-anchor" href="#respuesta-a-incidentes" aria-label="Permalink to &quot;Respuesta a incidentes&quot;">​</a></h2><p>Mantén responsables, canales de escalamiento, procedimiento para revocar claves, preservar evidencia, informar a afectados y reconciliar operaciones financieras. Registra fecha, alcance, decisiones y acciones posteriores.</p>',16)])])}const h=a(i,[["render",n]]);export{m as __pageData,h as default};
